mapper.sql:
select
inventory.*,
sku.*,
item.*,
rack.rack_name,
loc.location_name
from wms_inventory inventory
inner join wms_item_sku sku on inventory.sku_id=sku.id
inner join wms_item item on sku.item_id=item.id
left join wms_rack rack on inventory.rack_id=rack.id
left join wms_location loc on inventory.location_id=loc.id


        item.item_name like concat('%', #{bo.itemName}, '%')


        and item.item_code like concat('%', #{bo.itemCode}, '%')


        and sku.sku_name like concat('%', #{bo.skuName}, '%')


        and item.item_category=#{bo.itemCategory}


        and item.id=#{bo.itemId}


        and inventory.warehouse_id=#{bo.warehouseId}


        and inventory.area_id=#{bo.areaId}


        and inventory.rack_id=#{bo.rackId}


        and inventory.location_id=#{bo.locationId}


        and inventory.quantity>=#{bo.minQuantity}

mapper.update:
UPDATE wms_inventory
SET quantity = quantity + #{delta}
WHERE warehouse_id = #{warehouseId}
  AND area_id = #{areaId}
  AND sku_id = #{skuId}

      AND rack_id = #{rackId}
      AND rack_id IS NULL


      AND location_id = #{locationId}
      AND location_id IS NULL

mapper.select:
SELECT sku_id AS "skuId", COALESCE(SUM(quantity), 0) AS "totalQuantity"
FROM wms_inventory
WHERE quantity IS NOT NULL

    AND warehouse_id = #{warehouseId}


    AND area_id = #{areaId}


    AND rack_id = #{rackId}

GROUP BY sku_id

mapper.delete:
DELETE FROM wms_inventory
WHERE quantity <= 0
  AND warehouse_id = #{warehouseId}
  AND area_id = #{areaId}
  AND sku_id = #{skuId}

      AND rack_id = #{rackId}
      AND rack_id IS NULL


      AND location_id = #{locationId}
      AND location_id IS NULL

update.foreach:
UPDATE wms_inventory
SET quantity = quantity + #{it.quantity}
WHERE warehouse_id = #{it.warehouseId}
  AND area_id = #{it.areaId}
  AND sku_id = #{it.skuId}

      AND rack_id = #{it.rackId}
      AND rack_id IS NULL


      AND location_id = #{it.locationId}
      AND location_id IS NULL

mapper.delete:
DELETE FROM wms_inventory WHERE quantity <= 0 AND (

    (warehouse_id = #{it.warehouseId} AND area_id = #{it.areaId} AND sku_id = #{it.skuId}

        AND rack_id = #{it.rackId}
        AND rack_id IS NULL


        AND location_id = #{it.locationId}
        AND location_id IS NULL
    )

)
